<?php
namespace Tests\Feature;
use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Http;use App\Models\{User,MarketingCampaign,MarketingPost};
class MarketingAttributionTest extends TestCase {use RefreshDatabase;
 public function test_consent_is_explicit_and_link_does_not_accept_arbitrary_redirect(){Http::preventStrayRequests();$this->postJson('/marketing/tracking/consent',['accepted'=>false])->assertOk()->assertJsonPath('accepted',false);$this->get('/m/r/invalid?url=https://evil.example')->assertNotFound();Http::assertNothingSent();}
 public function test_dashboard_does_not_fabricate_metrics(){config(['marketing.attribution_enabled'=>false]);Http::preventStrayRequests();$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$this->getJson('/admin/marketing/analytics/data')->assertOk()->assertJsonPath('collection','disabled')->assertJsonPath('paid_orders',0);Http::assertNothingSent();}
 public function test_page_events_require_consent_and_retry_is_deduplicated(){Http::preventStrayRequests();config(['marketing.attribution_enabled'=>true]);$payload=['navigation_id'=>(string)\Illuminate\Support\Str::uuid(),'item_id'=>null];$this->postJson('/marketing/tracking/page',$payload)->assertOk()->assertJsonPath('tracked',false);$u=User::factory()->create();$m=app(\App\Services\Marketing\MarketingPosts::class)->merchant();$l=(string)\Illuminate\Support\Str::uuid();\Illuminate\Support\Facades\DB::table('marketing_tracking_links')->insert(['id'=>$l,'campaign_id'=>(string)\Illuminate\Support\Str::uuid(),'post_id'=>(string)\Illuminate\Support\Str::uuid(),'destination_id'=>(string)\Illuminate\Support\Str::uuid(),'merchant_key'=>$m,'user_id'=>$u->id,'post_version'=>1,'destination_url'=>'http://localhost']);$session=['marketing'=>['consent'=>true,'last'=>['id'=>$l,'at'=>now()->timestamp,'session'=>'visitor']]];$this->withSession($session)->postJson('/marketing/tracking/page',$payload)->assertOk()->assertJsonPath('tracked',true);$this->postJson('/marketing/tracking/page',$payload)->assertOk();$this->assertSame(1,\Illuminate\Support\Facades\DB::table('marketing_analytics_events')->where('kind','page_view')->count());$this->postJson('/marketing/tracking/consent',['accepted'=>false])->assertOk();$this->postJson('/marketing/tracking/page',['navigation_id'=>(string)\Illuminate\Support\Str::uuid()])->assertJsonPath('tracked',false);$this->assertSame(1,\Illuminate\Support\Facades\DB::table('marketing_analytics_events')->where('kind','page_view')->count());Http::assertNothingSent();}
}
